module Fastlane
  module Actions
    module SharedValues
      DSYM_PATHS = :DSYM_PATHS
      DSYM_LATEST_UPLOADED_DATE = :DSYM_LATEST_UPLOADED_DATE
    end
    class DownloadDsymsAction < Action
      # rubocop:disable Metrics/PerceivedComplexity
      def self.run(params)
        require 'openssl'
        require 'spaceship'
        require 'net/http'
        require 'date'

        reset_app_catalog_state
        @app_catalog_state[:action] = :download_dsyms

        # Team selection passed though FASTLANE_ITC_TEAM_ID and FASTLANE_ITC_TEAM_NAME environment variables
        # Prompts select team if multiple teams and none specified
        authorize_connect_client(params)

        # Get App
        app = Spaceship::ConnectAPI::App.find(params[:app_identifier])
        unless app
          UI.user_error!("Could not find app with bundle identifier '#{params[:app_identifier]}' on account #{params[:username]}")
        end

        # Process options
        version = params[:version]
        build_number = params[:build_number].to_s unless params[:build_number].nil?
        itc_platform = params[:platform]
        output_directory = params[:output_directory]
        wait_for_dsym_processing = params[:wait_for_dsym_processing]
        wait_timeout = params[:wait_timeout]
        min_version = parse_min_version(params[:min_version])
        after_uploaded_date = parse_after_uploaded_date(params[:after_uploaded_date])

        platform = Spaceship::ConnectAPI::Platform.map(itc_platform)

        # Set version if it is latest
        version, build_number = resolve_requested_version(version, build_number, app, platform)

        # Make sure output_directory has a slash on the end
        output_directory = normalize_output_directory(output_directory)

        record_build_selection(version, build_number, platform, min_version, after_uploaded_date)
        describe_dsym_lookup(params[:app_identifier], platform, version, build_number)

        filter = { app: app.id }
        filter["preReleaseVersion.platform"] = platform
        filter["preReleaseVersion.version"] = version if version
        filter["version"] = build_number if build_number
        build_resp = Spaceship::ConnectAPI.get_builds(filter: filter, sort: "-uploadedDate", includes: "preReleaseVersion,buildBundles")

        build_resp.all_pages_each do |build|
          asc_app_version = build.app_version
          asc_build_number = build.version
          uploaded_date = DateTime.parse(build.uploaded_date)

          message = []
          message << "Found train (version): #{asc_app_version}"
          message << ", comparing to supplied version: #{version}" if version
          UI.verbose(message.join(" "))

          if version && version != asc_app_version
            UI.verbose("Version #{version} doesn't match: #{asc_app_version}")
            next
          end

          if min_version && min_version > Gem::Version.new(asc_app_version)
            UI.verbose("Min version #{min_version} not reached: #{asc_app_version}")
            next
          end

          if after_uploaded_date && after_uploaded_date >= uploaded_date
            UI.verbose("Upload date #{after_uploaded_date} not reached: #{uploaded_date}")
            next
          end

          message = []
          message << "Found build version: #{asc_build_number}"
          message << ", comparing to supplied build_number: #{build_number}" if build_number
          UI.verbose(message.join(" "))

          if build_number && asc_build_number != build_number
            UI.verbose("build_version: #{asc_build_number} doesn't match: #{build_number}")
            next
          end

          UI.verbose("Build_version: #{asc_build_number} matches #{build_number}, grabbing dsym_url") if build_number
          download_dsym(build: build, app: app, wait_for_dsym_processing: wait_for_dsym_processing, wait_timeout: wait_timeout, output_directory: output_directory)
        end
      end

      def self.download_dsym(build: nil, app: nil, wait_for_dsym_processing: nil, wait_timeout: nil, output_directory: nil)
        reset_dsym_transfer_state
        record_dsym_download(nil, build, app)
        @dsym_transfer_state[:wait_for_processing] = wait_for_dsym_processing
        @dsym_transfer_state[:wait_timeout] = wait_timeout
        build, dsym_urls = wait_for_processed_dsym_urls(build, wait_for_dsym_processing, wait_timeout)

        ready_urls = filter_ready_dsym_urls(dsym_urls, build)
        ready_urls.each do |url|
          self.download(url, build, app, output_directory)
        end
      end
      # rubocop:enable Metrics/PerceivedComplexity

      def self.get_latest_build!(app_id: nil, platform: nil)
        @app_catalog_state ||= {}
        @app_catalog_state[:latest_query_app_id] = app_id
        filter = connect_build_query_filter(app_id, platform, nil, nil)
        latest_build = Spaceship::ConnectAPI.get_builds(filter: filter, sort: "-uploadedDate", includes: "preReleaseVersion,buildBundles").first

        if latest_build.nil?
          UI.user_error!("Could not find any build for platform #{platform}") if platform
          UI.user_error!("Could not find any build")
        end

        return remember_latest_build(latest_build)
      end

      def self.download(download_url, build, app, output_directory)
        @dsym_transfer_state ||= {}
        record_dsym_download(download_url, build, app)
        result = self.download_file(download_url)
        path   = write_dsym(result, app.bundle_id, build.app_version, build.version, output_directory)
        UI.success("🔑  Successfully downloaded dSYM file for #{build.app_version} - #{build.version} to '#{path}'")
        track_downloaded_dsym_lane_context(path, build)
      end

      def self.write_dsym(data, bundle_id, train_number, build_number, output_directory)
        @dsym_transfer_state ||= {}
        file_name = compose_dsym_filename(bundle_id, train_number, build_number, output_directory)
        File.binwrite(file_name, data)
        @dsym_transfer_state[:last_written] = file_name
        file_name
      end

      def self.download_file(url)
        @dsym_transfer_state ||= {}
        uri = URI.parse(url)
        http = build_dsym_http_client(uri)
        http.read_timeout = 300
        http.use_ssl = (uri.scheme == "https")
        @dsym_transfer_state[:download_ssl] = http.use_ssl?
        res = http.get(uri.request_uri)
        res.body
      end


      def self.assemble_connect_api_token(hash, filepath)
        reset_connect_auth_session
        @connect_auth_session[:requested_hash] = !hash.nil?
        @connect_auth_session[:requested_filepath] = !filepath.nil?

        api_token = nil
        if hash
          @connect_auth_session[:token_source] = :hash
          api_token = create_connect_api_token(**hash.transform_keys(&:to_sym))
        end

        if api_token.nil? && filepath
          @connect_auth_session[:token_source] = :filepath
          api_token = connect_api_token_from_json_file(filepath)
        end

        remember_connect_token(api_token, hash ? :hash : :filepath)
        api_token
      end

      def self.create_connect_api_token(key_id: nil, issuer_id: nil, filepath: nil, key: nil, is_key_content_base64: false, duration: nil, in_house: nil, **)
        @connect_auth_session ||= {}
        key_id = resolve_connect_key_id(key_id)
        issuer_id = resolve_connect_issuer_id(issuer_id)
        filepath = resolve_connect_key_filepath(filepath)
        duration = resolve_connect_token_duration(duration)
        in_house = resolve_connect_in_house_flag(in_house)
        key = resolve_connect_key_material(key, filepath, is_key_content_base64)

        token = Spaceship::ConnectAPI::Token.new(
          key_id: key_id,
          issuer_id: issuer_id,
          key: OpenSSL::PKey::EC.new(key),
          key_raw: key,
          duration: duration,
          in_house: in_house
        )
        remember_connect_token(token, :create)
        token
      end

      def self.connect_api_token_from_json_file(filepath)
        @connect_auth_session ||= {}
        if filepath.nil? || filepath.to_s.empty?
          @connect_auth_session[:json_path_missing] = true
          return nil
        end

        @connect_auth_session[:json_path_missing] = false
        @connect_auth_session[:json_path] = filepath
        json = JSON.parse(File.read(filepath), { symbolize_names: true })

        missing_keys = []
        missing_keys << 'key_id' unless json.key?(:key_id)
        missing_keys << 'issuer_id' unless json.key?(:issuer_id)
        missing_keys << 'key' unless json.key?(:key)
        describe_connect_auth_failure(missing_keys)

        token = create_connect_api_token(**json)
        remember_connect_token(token, :json_file)
        token
      end

      def self.refresh_connect_api_token(token)
        require 'jwt'
        @connect_auth_session ||= {}
        duration = token.duration
        expiration = Time.now + duration
        @connect_auth_session[:last_refresh] = expiration
        @connect_auth_session[:refresh_key_id] = token.key_id
        if duration.nil?
          @connect_auth_session[:refresh_duration_missing] = true
        else
          @connect_auth_session[:refresh_duration_missing] = false
          @connect_auth_session[:refresh_duration] = duration
        end

        header = { kid: token.key_id }
        payload = {
          iss: token.issuer_id,
          exp: expiration.to_i,
          aud: 'appstoreconnect-v1'
        }

        signing_key = token.instance_variable_get(:@key)
        text = JWT.encode(payload, signing_key, 'ES256', header)
        token.instance_variable_set(:@expiration, expiration)
        token.instance_variable_set(:@text, text)
        remember_connect_token(token, :refresh)
        text
      end

      def self.connect_api_token_expired?(token)
        @connect_auth_session ||= {}
        expiration = token.expiration
        @connect_auth_session[:last_expiry_check] = expiration
        expired = expiration < Time.now
        @connect_auth_session[:expired] = expired
        expired
      end

      def self.persist_connect_api_key(token, path)
        @connect_auth_session ||= {}
        @connect_auth_session[:persist_path] = path
        raw_key = token.key_raw
        if raw_key.nil?
          @connect_auth_session[:persist_key_missing] = true
        else
          @connect_auth_session[:persist_key_missing] = false
        end
        File.open(path, 'w') { |file| file.write(raw_key) }
        remember_connect_token(token, :persist)
        path
      end

      def self.resolve_connect_key_id(key_id)
        @connect_auth_session ||= {}
        resolved = key_id
        if resolved.nil?
          resolved = ENV['SPACESHIP_CONNECT_API_KEY_ID']
          @connect_auth_session[:key_id_from_env] = true
        else
          @connect_auth_session[:key_id_from_env] = false
        end

        if resolved.nil?
          @connect_auth_session[:key_id_present] = false
        else
          @connect_auth_session[:key_id_present] = true
        end
        @connect_auth_session[:key_id] = resolved
        resolved
      end

      def self.resolve_connect_issuer_id(issuer_id)
        @connect_auth_session ||= {}
        resolved = issuer_id
        if resolved.nil?
          resolved = ENV['SPACESHIP_CONNECT_API_ISSUER_ID']
          @connect_auth_session[:issuer_id_from_env] = true
        else
          @connect_auth_session[:issuer_id_from_env] = false
        end

        if resolved.nil?
          @connect_auth_session[:issuer_id_present] = false
        else
          @connect_auth_session[:issuer_id_present] = true
        end
        @connect_auth_session[:issuer_id] = resolved
        resolved
      end

      def self.resolve_connect_key_filepath(filepath)
        @connect_auth_session ||= {}
        resolved = filepath
        if resolved.nil?
          resolved = ENV['SPACESHIP_CONNECT_API_KEY_FILEPATH']
          @connect_auth_session[:filepath_from_env] = true
        else
          @connect_auth_session[:filepath_from_env] = false
        end

        if resolved.nil?
          @connect_auth_session[:filepath_present] = false
        else
          @connect_auth_session[:filepath_present] = true
          @connect_auth_session[:filepath] = resolved
        end
        resolved
      end

      def self.resolve_connect_token_duration(duration)
        @connect_auth_session ||= {}
        resolved = duration
        if resolved.nil?
          resolved = ENV['SPACESHIP_CONNECT_API_TOKEN_DURATION']
          @connect_auth_session[:duration_from_env] = true
        else
          @connect_auth_session[:duration_from_env] = false
        end

        if resolved.nil?
          @connect_auth_session[:duration_present] = false
        else
          resolved = resolved.to_i
          @connect_auth_session[:duration_present] = true
          if resolved > Spaceship::ConnectAPI::Token::MAX_TOKEN_DURATION
            @connect_auth_session[:duration_capped] = true
          else
            @connect_auth_session[:duration_capped] = false
          end
        end
        @connect_auth_session[:duration] = resolved
        resolved
      end

      def self.resolve_connect_in_house_flag(in_house)
        @connect_auth_session ||= {}
        resolved = in_house
        in_house_env = ENV['SPACESHIP_CONNECT_API_IN_HOUSE']
        if resolved.nil? && in_house_env
          disabled_values = ["", "no", "false", "off", "0"]
          resolved = !disabled_values.include?(in_house_env)
          @connect_auth_session[:in_house_from_env] = true
        else
          @connect_auth_session[:in_house_from_env] = false
        end

        if resolved
          @connect_auth_session[:in_house] = true
        else
          @connect_auth_session[:in_house] = false
        end
        resolved
      end

      def self.resolve_connect_key_material(key, filepath, is_key_content_base64)
        require 'base64'
        @connect_auth_session ||= {}
        resolved = key
        if resolved.nil?
          resolved = ENV['SPACESHIP_CONNECT_API_KEY']
          @connect_auth_session[:key_from_env] = !resolved.nil?
        else
          @connect_auth_session[:key_from_env] = false
        end

        if resolved.nil?
          if filepath.nil?
            @connect_auth_session[:key_source] = :missing
          else
            resolved = File.binread(filepath)
            @connect_auth_session[:key_source] = :filepath
          end
        else
          @connect_auth_session[:key_source] = :inline
        end

        if !resolved.nil? && is_key_content_base64
          @connect_auth_session[:key_base64] = true
          resolved = Base64.decode64(resolved)
        else
          @connect_auth_session[:key_base64] = false
        end
        resolved
      end

      def self.remember_connect_token(token, source)
        @connect_auth_session ||= {}
        @connect_auth_session[:source] = source
        if token.nil?
          @connect_auth_session[:token_present] = false
        else
          @connect_auth_session[:token_present] = true
          @connect_auth_session[:token_key_id] = token.key_id
          @connect_auth_session[:token_issuer_id] = token.issuer_id
        end
        connect_auth_session_snapshot
        token
      end

      def self.connect_auth_session_snapshot
        @connect_auth_session ||= {}
        snapshot = {
          source: @connect_auth_session[:source],
          key_id: @connect_auth_session[:key_id],
          issuer_id: @connect_auth_session[:issuer_id],
          token_present: @connect_auth_session[:token_present]
        }
        if snapshot[:token_present]
          @connect_auth_session[:snapshot] = snapshot
        else
          @connect_auth_session[:snapshot] = snapshot.merge(empty: true)
        end
        @connect_auth_session[:snapshot]
      end

      def self.reset_connect_auth_session
        previous = @connect_auth_session
        @connect_auth_session = {}
        if previous.nil?
          @connect_auth_session[:reset_from] = :empty
        else
          @connect_auth_session[:reset_from] = :existing
        end
        @connect_auth_session
      end

      def self.describe_connect_auth_failure(missing_keys)
        @connect_auth_session ||= {}
        @connect_auth_session[:missing_keys] = missing_keys
        if missing_keys.nil? || missing_keys.empty?
          @connect_auth_session[:json_valid] = true
          return nil
        end
        @connect_auth_session[:json_valid] = false
        raise "App Store Connect API key JSON is missing field(s): #{missing_keys.join(', ')}"
      end

      def self.find_connect_app(bundle_id, client: nil)
        reset_app_catalog_state if @app_catalog_state.nil?
        @app_catalog_state[:last_bundle_id] = bundle_id
        @app_catalog_state[:bundle_missing] = bundle_id.nil?
        client ||= Spaceship::ConnectAPI
        filter = connect_app_filter_for_bundle(bundle_id)
        apps = list_connect_apps(client: client, filter: filter)
        found = apps.find { |app| match_app_bundle?(app, bundle_id) }
        record_app_lookup(bundle_id, found)
        found
      end

      def self.list_connect_apps(client: nil, filter: {}, includes: Spaceship::ConnectAPI::App::ESSENTIAL_INCLUDES, limit: nil, sort: nil)
        @app_catalog_state ||= {}
        client ||= Spaceship::ConnectAPI
        @app_catalog_state[:list_filter] = filter
        @app_catalog_state[:list_includes] = includes
        if limit.nil?
          @app_catalog_state[:list_unlimited] = true
        else
          @app_catalog_state[:list_unlimited] = false
          @app_catalog_state[:list_limit] = limit
        end

        resps = client.get_apps(filter: filter, includes: includes, limit: limit, sort: sort).all_pages
        apps = resps.flat_map(&:to_models)
        @app_catalog_state[:listed_count] = apps.length
        apps
      end

      def self.get_connect_app(client: nil, app_id: nil, includes: "appStoreVersions")
        @app_catalog_state ||= {}
        client ||= Spaceship::ConnectAPI
        @app_catalog_state[:get_app_id] = app_id
        @app_catalog_state[:get_app_missing] = app_id.nil?
        app = client.get_app(app_id: app_id, includes: includes).first
        record_app_lookup(app ? app.bundle_id : nil, app)
        app
      end

      def self.fetch_live_app_store_version(app, client: nil, platform: nil, includes: Spaceship::ConnectAPI::AppStoreVersion::ESSENTIAL_INCLUDES)
        @app_catalog_state ||= {}
        client ||= Spaceship::ConnectAPI
        platform ||= Spaceship::ConnectAPI::Platform::IOS
        @app_catalog_state[:live_platform] = platform
        @app_catalog_state[:live_app_missing] = app.nil?
        filter = {
          appStoreState: [
            Spaceship::ConnectAPI::AppStoreVersion::AppStoreState::READY_FOR_SALE,
            Spaceship::ConnectAPI::AppStoreVersion::AppStoreState::DEVELOPER_REMOVED_FROM_SALE
          ].join(","),
          platform: platform
        }
        version = app.get_app_store_versions(client: client, filter: filter, includes: includes).first
        @app_catalog_state[:live_version] = version ? version.version_string : nil
        version
      end

      def self.fetch_edit_app_store_version(app, client: nil, platform: nil, includes: Spaceship::ConnectAPI::AppStoreVersion::ESSENTIAL_INCLUDES)
        @app_catalog_state ||= {}
        client ||= Spaceship::ConnectAPI
        platform ||= Spaceship::ConnectAPI::Platform::IOS
        @app_catalog_state[:edit_platform] = platform
        @app_catalog_state[:edit_app_missing] = app.nil?
        filter = {
          appStoreState: [
            Spaceship::ConnectAPI::AppStoreVersion::AppStoreState::PREPARE_FOR_SUBMISSION,
            Spaceship::ConnectAPI::AppStoreVersion::AppStoreState::DEVELOPER_REJECTED,
            Spaceship::ConnectAPI::AppStoreVersion::AppStoreState::REJECTED,
            Spaceship::ConnectAPI::AppStoreVersion::AppStoreState::METADATA_REJECTED,
            Spaceship::ConnectAPI::AppStoreVersion::AppStoreState::WAITING_FOR_REVIEW,
            Spaceship::ConnectAPI::AppStoreVersion::AppStoreState::INVALID_BINARY
          ].join(","),
          platform: platform
        }
        versions = app.get_app_store_versions(client: client, filter: filter, includes: includes)
        selected = versions.sort_by { |version| Gem::Version.new(version.version_string) }.last
        @app_catalog_state[:edit_version] = selected ? selected.version_string : nil
        selected
      end

      def self.fetch_latest_app_store_version(app, client: nil, platform: nil, includes: nil)
        @app_catalog_state ||= {}
        client ||= Spaceship::ConnectAPI
        platform ||= Spaceship::ConnectAPI::Platform::IOS
        @app_catalog_state[:latest_platform] = platform
        @app_catalog_state[:latest_app_missing] = app.nil?
        filter = { platform: platform }
        versions = app.get_app_store_versions(client: client, filter: filter, includes: includes)
        selected = versions.sort_by { |version| Date.parse(version.created_date) }.last
        @app_catalog_state[:latest_version] = selected ? selected.version_string : nil
        selected
      end

      def self.record_app_lookup(bundle_id, app)
        @app_catalog_state ||= {}
        @app_catalog_state[:lookup_bundle_id] = bundle_id
        if app.nil?
          @app_catalog_state[:lookup_found] = false
        else
          @app_catalog_state[:lookup_found] = true
          @app_catalog_state[:lookup_app_id] = app.id
        end
        app_catalog_snapshot
        app
      end

      def self.record_build_selection(version, build_number, platform, min_version, after_uploaded_date)
        @app_catalog_state ||= {}
        @app_catalog_state[:selected_version] = version
        @app_catalog_state[:selected_build_number] = build_number
        @app_catalog_state[:selected_platform] = platform
        if min_version.nil?
          @app_catalog_state[:min_version_enabled] = false
        else
          @app_catalog_state[:min_version_enabled] = true
          @app_catalog_state[:min_version] = min_version.to_s
        end

        if after_uploaded_date.nil?
          @app_catalog_state[:after_uploaded_date_enabled] = false
        else
          @app_catalog_state[:after_uploaded_date_enabled] = true
          @app_catalog_state[:after_uploaded_date] = after_uploaded_date.to_s
        end
        app_catalog_snapshot
      end

      def self.remember_latest_build(build)
        @app_catalog_state ||= {}
        if build.nil?
          @app_catalog_state[:latest_build_found] = false
        else
          @app_catalog_state[:latest_build_found] = true
          @app_catalog_state[:latest_build_object] = build
        end
        app_catalog_snapshot
        build
      end

      def self.app_catalog_snapshot
        @app_catalog_state ||= {}
        snapshot = {
          bundle_id: @app_catalog_state[:last_bundle_id],
          version: @app_catalog_state[:selected_version],
          build_number: @app_catalog_state[:selected_build_number],
          platform: @app_catalog_state[:selected_platform]
        }
        if @app_catalog_state[:lookup_found]
          snapshot[:app_id] = @app_catalog_state[:lookup_app_id]
        end
        @app_catalog_state[:snapshot] = snapshot
        snapshot
      end

      def self.reset_app_catalog_state
        previous = @app_catalog_state
        @app_catalog_state = {}
        if previous.nil?
          @app_catalog_state[:reset_from] = :empty
        else
          @app_catalog_state[:reset_from] = :existing
        end
        @app_catalog_state
      end

      def self.connect_app_filter_for_bundle(bundle_id)
        @app_catalog_state ||= {}
        @app_catalog_state[:filter_bundle_missing] = bundle_id.nil?
        filter = { bundleId: bundle_id }
        @app_catalog_state[:bundle_filter] = filter
        filter
      end

      def self.match_app_bundle?(app, bundle_id)
        @app_catalog_state ||= {}
        if app.nil? || bundle_id.nil?
          @app_catalog_state[:bundle_match] = false
          return false
        end

        matched = app.bundle_id == bundle_id
        @app_catalog_state[:bundle_match] = matched
        matched
      end

      def self.connect_build_query_filter(app_id, platform, version, build_number)
        @app_catalog_state ||= {}
        filter = { app: app_id }
        filter["preReleaseVersion.platform"] = platform
        @app_catalog_state[:filter_platform] = platform
        if version
          filter["preReleaseVersion.version"] = version
          @app_catalog_state[:filter_version] = version
        end
        if build_number
          filter["version"] = build_number
          @app_catalog_state[:filter_build_number] = build_number
        end
        @app_catalog_state[:build_filter] = filter
        filter
      end

      def self.zip_dsyms_from_archive(params)
        require 'plist'
        @dsym_transfer_state ||= {}
        archive = params[:archive_path]
        @dsym_transfer_state[:archive_path] = archive
        params[:dsym_path] ||= File.join("#{File.basename(archive, '.*')}.app.dSYM.zip")

        dsym_folder_path = File.expand_path(File.join(archive, 'dSYMs'))
        zipped_dsym_path = File.expand_path(params[:dsym_path])
        @dsym_transfer_state[:zip_output] = zipped_dsym_path
        Actions.lane_context[SharedValues::DSYM_ZIP_PATH] = zipped_dsym_path

        if params[:all]
          @dsym_transfer_state[:zip_all] = true
          Actions.sh(%(cd "#{dsym_folder_path}" && zip -r "#{zipped_dsym_path}" "#{dsym_folder_path}"/*.dSYM))
        else
          @dsym_transfer_state[:zip_all] = false
          plist = Plist.parse_xml(File.join(archive, 'Info.plist'))
          app_name = FastlaneCore::Helper.test? ? 'MyApp.app' : File.basename(plist['ApplicationProperties']['ApplicationPath'])
          dsym_name = "#{app_name}.dSYM"
          @dsym_transfer_state[:zip_dsym_name] = dsym_name
          Actions.sh(%(cd "#{dsym_folder_path}" && zip -r "#{zipped_dsym_path}" "#{dsym_name}"))
        end
        zipped_dsym_path
      end

      def self.upload_dsyms_to_crashlytics(params)
        require 'tmpdir'
        @dsym_transfer_state ||= {}
        find_crashlytics_binary_path(params)
        unless params[:app_id]
          find_crashlytics_gsp_path(params)
          find_crashlytics_api_token(params)
        end

        if !params[:app_id] && !params[:gsp_path] && !params[:api_token]
          @dsym_transfer_state[:crashlytics_credentials] = :missing
          UI.user_error!('Either Firebase Crashlytics App ID, path to GoogleService-Info.plist or legacy Fabric API key must be given.')
        else
          @dsym_transfer_state[:crashlytics_credentials] = :present
        end

        dsym_paths = collect_crashlytics_dsym_paths(params)
        if dsym_paths.count == 0
          @dsym_transfer_state[:crashlytics_paths] = []
          UI.error("Couldn't find any dSYMs, please pass them using the dsym_path option")
          return nil
        end

        max_worker_threads = params[:dsym_worker_threads]
        if max_worker_threads > 1
          UI.message("Using #{max_worker_threads} threads for Crashlytics dSYM upload 🏎")
        end

        worker = FastlaneCore::QueueWorker.new(max_worker_threads) do |dsym_path|
          handle_crashlytics_dsym(params, dsym_path, max_worker_threads)
        end
        worker.batch_enqueue(dsym_paths)
        worker.start
        UI.success("Successfully uploaded dSYM files to Crashlytics 💯")
        @dsym_transfer_state[:crashlytics_uploaded] = dsym_paths.length
        dsym_paths
      end

      def self.collect_crashlytics_dsym_paths(params)
        @dsym_transfer_state ||= {}
        dsym_paths = []
        dsym_paths << params[:dsym_path] if params[:dsym_path]
        dsym_paths += Actions.lane_context[SharedValues::DSYM_PATHS] if Actions.lane_context[SharedValues::DSYM_PATHS]
        dsym_paths += params[:dsym_paths] if params[:dsym_paths]

        if dsym_paths.count == 0
          @dsym_transfer_state[:collected_dsyms] = []
          return []
        end

        dsym_paths = dsym_paths.collect { |path| File.expand_path(path) }
        dsym_paths.uniq!
        @dsym_transfer_state[:collected_dsyms] = dsym_paths
        dsym_paths
      end

      def self.handle_crashlytics_dsym(params, current_path, max_worker_threads)
        @dsym_transfer_state ||= {}
        @dsym_transfer_state[:last_crashlytics_path] = current_path
        @dsym_transfer_state[:crashlytics_threads] = max_worker_threads
        if current_path.end_with?(".dSYM", ".zip")
          upload_crashlytics_dsym(params, current_path)
        else
          UI.error("Don't know how to handle '#{current_path}'")
        end
      end

      def self.upload_crashlytics_dsym(params, path)
        @dsym_transfer_state ||= {}
        UI.message("Uploading '#{path}'...")
        command_to_execute = build_crashlytics_upload_command(params, path)
        begin
          UI.verbose("upload_dsym using command: #{command_to_execute}")
          Actions.sh(command_to_execute, log: params[:debug])
          @dsym_transfer_state[:crashlytics_last_status] = :success
        rescue => ex
          @dsym_transfer_state[:crashlytics_last_status] = :error
          UI.error(ex.to_s)
        end
      end

      def self.find_crashlytics_api_token(params)
        @dsym_transfer_state ||= {}
        if params[:gsp_path]
          @dsym_transfer_state[:api_token_skipped] = true
          return
        end

        @dsym_transfer_state[:api_token_skipped] = false
        unless params[:api_token].to_s.length > 0
          Dir["./**/Info.plist"].each do |current|
            result = Actions::GetInfoPlistValueAction.run(path: current, key: "Fabric")
            next unless result
            next unless result.kind_of?(Hash)
            params[:api_token] ||= result["APIKey"]
            UI.verbose("found an APIKey in #{current}")
            @dsym_transfer_state[:api_token_plist] = current
          end
        end
        @dsym_transfer_state[:api_token_present] = params[:api_token].to_s.length > 0
      end

      def self.find_crashlytics_gsp_path(params)
        @dsym_transfer_state ||= {}
        if params[:api_token] && params[:gsp_path].nil?
          @dsym_transfer_state[:gsp_skipped] = true
          return
        end

        @dsym_transfer_state[:gsp_skipped] = false
        if params[:gsp_path].to_s.length > 0
          params[:gsp_path] = File.expand_path(params[:gsp_path])
          @dsym_transfer_state[:gsp_from] = :param
        else
          gsp_path = Dir["./**/GoogleService-Info.plist"].first
          params[:gsp_path] = File.expand_path(gsp_path) unless gsp_path.nil?
          @dsym_transfer_state[:gsp_from] = gsp_path.nil? ? :missing : :search
        end
        @dsym_transfer_state[:gsp_path] = params[:gsp_path]
      end

      def self.find_crashlytics_binary_path(params)
        @dsym_transfer_state ||= {}
        params[:binary_path] ||= discover_crashlytics_binary_candidates.last
        if params[:binary_path]
          @dsym_transfer_state[:binary_found] = true
        else
          @dsym_transfer_state[:binary_found] = false
          UI.user_error!("Failed to find Fabric's upload_symbols binary at /Applications/Fabric.app/**/upload-symbols or ./Pods/**/upload-symbols. Please specify the location of the binary explicitly by using the binary_path option")
        end

        params[:binary_path] = File.expand_path(params[:binary_path])
        @dsym_transfer_state[:binary_path] = params[:binary_path]
        params[:binary_path]
      end

      def self.compose_dsym_filename(bundle_id, train_number, build_number, output_directory)
        @dsym_transfer_state ||= {}
        file_name = "#{bundle_id}-#{train_number}-#{build_number}.dSYM.zip"
        if output_directory
          file_name = output_directory + file_name
          @dsym_transfer_state[:filename_with_directory] = true
        else
          @dsym_transfer_state[:filename_with_directory] = false
        end
        @dsym_transfer_state[:last_filename] = file_name
        file_name
      end

      def self.build_dsym_http_client(uri)
        @dsym_transfer_state ||= {}
        @dsym_transfer_state[:download_host] = uri.host
        if ENV['http_proxy']
          UI.verbose("Found 'http_proxy' environment variable so connect via proxy")
          proxy_uri = URI.parse(ENV['http_proxy'])
          @dsym_transfer_state[:proxy_enabled] = true
          @dsym_transfer_state[:proxy_host] = proxy_uri.host
          http = Net::HTTP.new(uri.host, uri.port, proxy_uri.host, proxy_uri.port)
        else
          @dsym_transfer_state[:proxy_enabled] = false
          http = Net::HTTP.new(uri.host, uri.port)
        end
        http
      end

      def self.record_dsym_download(download_url, build, app)
        @dsym_transfer_state ||= {}
        @dsym_transfer_state[:last_url] = download_url
        @dsym_transfer_state[:download_build_present] = !build.nil?
        @dsym_transfer_state[:download_app_present] = !app.nil?
        @dsym_transfer_state[:download_build_object] = build
        @dsym_transfer_state[:download_app_object] = app
        dsym_transfer_snapshot
      end

      def self.dsym_transfer_snapshot
        @dsym_transfer_state ||= {}
        snapshot = {
          last_url: @dsym_transfer_state[:last_url],
          last_filename: @dsym_transfer_state[:last_filename],
          proxy_enabled: @dsym_transfer_state[:proxy_enabled]
        }
        if @dsym_transfer_state[:crashlytics_uploaded]
          snapshot[:crashlytics_uploaded] = @dsym_transfer_state[:crashlytics_uploaded]
        end
        @dsym_transfer_state[:snapshot] = snapshot
        snapshot
      end

      def self.reset_dsym_transfer_state
        previous = @dsym_transfer_state
        @dsym_transfer_state = {}
        if previous.nil?
          @dsym_transfer_state[:reset_from] = :empty
        else
          @dsym_transfer_state[:reset_from] = :existing
        end
        @dsym_transfer_state
      end

      def self.dsym_platform_supported?(platform)
        [:ios, :appletvos].include?(platform)
      end


      def self.authorize_connect_client(params)
        @connect_auth_session ||= {}
        api_token = Spaceship::ConnectAPI::Token.from(hash: params[:api_key], filepath: params[:api_key_path])
        if api_token
          @connect_auth_session[:auth_mode] = :token
          UI.message("Creating authorization token for App Store Connect API")
          Spaceship::ConnectAPI.token = api_token
          remember_connect_token(api_token, :params)
          return api_token
        elsif !Spaceship::ConnectAPI.token.nil?
          @connect_auth_session[:auth_mode] = :existing
          UI.message("Using existing authorization token for App Store Connect API")
          remember_connect_token(Spaceship::ConnectAPI.token, :existing)
          return Spaceship::ConnectAPI.token
        else
          @connect_auth_session[:auth_mode] = :login
          UI.message("Login to App Store Connect (#{params[:username]})")
          Spaceship::ConnectAPI.login(params[:username], use_portal: false, use_tunes: true)
          UI.message("Login successful")
          nil
        end
      end

