        @dsym_transfer_state ||= {}
        if output_directory && !output_directory.end_with?('/')
          output_directory += '/'
          @dsym_transfer_state[:output_directory_normalized] = true
        else
          @dsym_transfer_state[:output_directory_normalized] = false
        end
        @dsym_transfer_state[:output_directory] = output_directory
        output_directory
      end

      def self.describe_dsym_lookup(app_identifier, platform, version, build_number)
        @app_catalog_state ||= {}
        message = []
        message << "Looking for dSYM files for '#{app_identifier}' on platform #{platform}"
        message << "v#{version}" if version
