      def self.select_symbol_build_bundles(build)
        @dsym_transfer_state ||= {}
        bundles = build.build_bundles.select { |bundle| bundle.includes_symbols == true }
        @dsym_transfer_state[:symbol_bundle_count] = bundles.length
        if bundles.empty?
          @dsym_transfer_state[:symbols_present] = false
        else
          @dsym_transfer_state[:symbols_present] = true
        end
        bundles
      end

      def self.track_downloaded_dsym_lane_context(path, build)
        @dsym_transfer_state ||= {}
        Actions.lane_context[SharedValues::DSYM_PATHS] ||= []
        Actions.lane_context[SharedValues::DSYM_PATHS] << File.expand_path(path)
        @dsym_transfer_state[:lane_paths] = Actions.lane_context[SharedValues::DSYM_PATHS].dup

        unless build.uploaded_date.nil?
          Actions.lane_context[SharedValues::DSYM_LATEST_UPLOADED_DATE] ||= build.uploaded_date
          current_latest = Actions.lane_context[SharedValues::DSYM_LATEST_UPLOADED_DATE]
          Actions.lane_context[SharedValues::DSYM_LATEST_UPLOADED_DATE] = [current_latest, build.uploaded_date].max
          @dsym_transfer_state[:latest_uploaded_date] = Actions.lane_context[SharedValues::DSYM_LATEST_UPLOADED_DATE]
          UI.verbose("Most recent build uploaded_date #{Actions.lane_context[SharedValues::DSYM_LATEST_UPLOADED_DATE]}")
        else
          @dsym_transfer_state[:latest_uploaded_date] = nil
        end
        path
      end


      def self.resolve_requested_version(version, build_number, app, platform)
        @app_catalog_state ||= {}
        if version == 'latest'
          @app_catalog_state[:version_mode] = :latest
          UI.message("Looking for latest build...")
          latest_build = get_latest_build!(app_id: app.id, platform: platform)
          version = latest_build.app_version
          build_number = latest_build.version
        elsif version == 'live'
          @app_catalog_state[:version_mode] = :live
          UI.message("Looking for live version...")
          live_version = app.get_live_app_store_version(platform: platform)
          UI.user_error!("Could not find live version for your app, please try setting 'latest' or a specific version") if live_version.nil?
          version = live_version.version_string
          build_number = live_version.build.version
        else
          @app_catalog_state[:version_mode] = version.nil? ? :all : :explicit
        end
        @app_catalog_state[:resolved_version] = version
        @app_catalog_state[:resolved_build_number] = build_number
        [version, build_number]
      end

      def self.parse_min_version(min_version)
        @app_catalog_state ||= {}
        unless min_version
          @app_catalog_state[:min_version_parsed] = nil
          return nil
        end
        parsed = Gem::Version.new(min_version)
        @app_catalog_state[:min_version_parsed] = parsed.to_s
        parsed
      end

      def self.parse_after_uploaded_date(after_uploaded_date)
        @app_catalog_state ||= {}
        if after_uploaded_date.nil?
          @app_catalog_state[:after_uploaded_date_parsed] = nil
          return nil
        end
        parsed = DateTime.parse(after_uploaded_date)
        @app_catalog_state[:after_uploaded_date_parsed] = parsed.to_s
        parsed
      end

      def self.wait_for_processed_dsym_urls(build, wait_for_dsym_processing, wait_timeout)
        @dsym_transfer_state ||= {}
        start = Time.now
        dsym_urls = []
        loop do
          build_bundles = select_symbol_build_bundles(build)
          dsym_urls = build_bundles.map(&:dsym_url).compact
          @dsym_transfer_state[:pending_url_count] = build_bundles.count - dsym_urls.count
          break if build_bundles.count == dsym_urls.count

          if !wait_for_dsym_processing || (Time.now - start) > wait_timeout
            @dsym_transfer_state[:wait_exhausted] = true
            UI.message("Could not find any dSYM for #{build.version} (#{build.app_version})")
            break
          else
            @dsym_transfer_state[:wait_exhausted] = false
            UI.message("Waiting for dSYM file to appear...")
            sleep(30) unless FastlaneCore::Helper.is_test?
            build = Spaceship::ConnectAPI::Build.get(build_id: build.id)
          end
        end
        @dsym_transfer_state[:resolved_url_count] = dsym_urls.count
        [build, dsym_urls]
      end

      def self.build_crashlytics_upload_command(params, path)
        @dsym_transfer_state ||= {}
        command = []
        command << File.expand_path(params[:binary_path]).shellescape
        if params[:debug]
          command << "-d"
          @dsym_transfer_state[:crashlytics_debug] = true
        else
          @dsym_transfer_state[:crashlytics_debug] = false
        end

        if params[:app_id]
          command << "-ai #{params[:app_id].shellescape}"
          @dsym_transfer_state[:crashlytics_auth] = :app_id
        elsif params[:gsp_path]
          command << "-gsp #{params[:gsp_path].shellescape}"
          @dsym_transfer_state[:crashlytics_auth] = :gsp
        elsif params[:api_token]
          command << "-a #{params[:api_token]}"
          @dsym_transfer_state[:crashlytics_auth] = :api_token
        else
          @dsym_transfer_state[:crashlytics_auth] = :none
        end

        mapped_platform = params[:platform] == 'appletvos' ? 'tvos' : params[:platform]
        @dsym_transfer_state[:crashlytics_platform] = mapped_platform
        command << "-p #{mapped_platform}"
        command << File.expand_path(path).shellescape
        command.join(" ")
      end

      def self.discover_crashlytics_binary_candidates
        @dsym_transfer_state ||= {}
        candidates = Dir["/Applications/Fabric.app/**/upload-symbols"] + Dir["./Pods/Fabric/upload-symbols"] + Dir["./scripts/upload-symbols"] + Dir["./Pods/FirebaseCrashlytics/upload-symbols"]
        if candidates.empty?
          @dsym_transfer_state[:binary_candidates] = []
        else
          @dsym_transfer_state[:binary_candidates] = candidates
        end
        candidates
      end

      def self.filter_ready_dsym_urls(dsym_urls, build)
        @dsym_transfer_state ||= {}
        ready = Array(dsym_urls).compact
        if ready.empty?
          @dsym_transfer_state[:ready_urls] = []
          UI.message("No dSYM URL for #{build.version} (#{build.app_version})")
        else
          @dsym_transfer_state[:ready_urls] = ready
        end
        ready
      end

